package com.example.starter.water.dto;

import java.math.BigDecimal;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 创建取水户请求：annualQuota 为年度许可总量，单位立方米（m³）。
 */
public record CreateUserRequest(
        @NotBlank String name,
        @NotBlank String riverSection,
        @NotNull @DecimalMin(value = "0.001", message = "年度许可总量必须为正") BigDecimal annualQuota) {
}

package com.example.starter.water.dto;

import java.math.BigDecimal;

/**
 * 取水户视图；restricted=true 表示当前处于生态流量预警“限取”状态。
 */
public record UserView(
        Long id,
        String name,
        String riverSection,
        BigDecimal annualQuota,
        boolean restricted) {
}

package com.example.starter.water.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 为取水户创建计量点请求。
 */
public record CreateMeterRequest(@NotBlank String name) {
}

package com.example.starter.water.dto;

/**
 * 计量点视图。
 */
public record MeterView(Long id, Long userId, String name) {
}

package com.example.starter.water.dto;

import java.math.BigDecimal;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;

/**
 * 月度取水计划申报请求。
 *
 * @param requestId 幂等键；指纹覆盖 requestId、取水户、自然月（UTC，yyyy-MM）、申报水量
 * @param userId    取水户 ID
 * @param month     自然月，UTC，格式 yyyy-MM
 * @param volume    申报水量，单位立方米（m³），必须为正
 */
public record DeclarationRequest(
        @NotBlank String requestId,
        @NotNull Long userId,
        @NotBlank @Pattern(regexp = "\\d{4}-(0[1-9]|1[0-2])", message = "月份格式必须为 yyyy-MM（UTC）") String month,
        @NotNull @DecimalMin(value = "0.001", message = "申报水量必须为正") BigDecimal volume) {
}

package com.example.starter.water.dto;

import java.math.BigDecimal;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotNull;

/**
 * 计量流量读数上报请求。
 *
 * @param meterPointId 计量点 ID
 * @param readingTime  表底时刻（UTC，ISO-8601，如 2026-01-15T08:00:00Z）
 * @param cumulative   表底累计读数（m³），必须非负
 */
public record ReadingRequest(
        @NotNull Long meterPointId,
        @NotNull String readingTime,
        @NotNull @DecimalMin(value = "0", message = "表底读数不能为负") BigDecimal cumulative) {
}

package com.example.starter.water.dto;

import java.math.BigDecimal;

/**
 * 读数上报结果；duplicate=true 表示同“计量点＋表底时刻”重复上报，未再次累计。
 *
 * @param delta      本次读数相对上一表底（按表底时刻排序）的增量（m³），归入 month 对应 UTC 自然月
 * @param duplicate  是否为重复上报
 */
public record ReadingResult(
        Long meterPointId,
        String readingTime,
        String month,
        BigDecimal cumulative,
        BigDecimal delta,
        boolean duplicate) {
}

package com.example.starter.water.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 河流生态流量预警触发请求；effectiveAt 缺省为当前 UTC 时刻。
 */
public record RestrictionRequest(
        @NotBlank String riverSection,
        String effectiveAt,
        String reason) {
}

package com.example.starter.water.dto;

/**
 * 限取触发结果；affectedUsers 为受影响河段进入“限取”状态的取水户数量。
 */
public record RestrictionResult(
        Long id,
        String riverSection,
        String effectiveAt,
        String reason,
        int affectedUsers) {
}

