    public List<RestrictionRow> findAllActive() {
        return jdbcTemplate.query(
                "SELECT id, river_section, effective_at, reason, active, created_at FROM restriction_event "
                        + "WHERE active = TRUE ORDER BY id",
                MAPPER);
    }
}

