49	/**
50	 * 取水许可水量分配与计量对冲应用服务。
51	 *
52	 * <p>核心规则：
53	 * <ul>
54	 *   <li>申报校验只依赖“已确认额度快照”（许可总量 − 上年结转扣减 − 本自然年各月最后已确认版本），
55	 *       计量读数不参与申报校验；</li>
56	 *   <li>受理边界按受理水量比较：达到剩余额度可受理（含边界），超出则整月拒绝、不产生新版本；</li>
57	 *   <li>限取期间新申报减半受理（受理水量=申报水量/2，m³ 保留 3 位小数四舍五入），已确认计划不变；</li>
58	 *   <li>封存按实际读数结算超许可部分，1:1 结转次年额度，封存为终态。</li>
59	 * </ul>
60	 */
61	@Service
62	public class WaterService {
63	
64	    private static final DateTimeFormatter MONTH_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM");
65	    private static final int VOLUME_SCALE = 3;
66	
67	    private final WaterUserRepository userRepository;
68	    private final MeterRepository meterRepository;
69	    private final PlanRepository planRepository;
70	    private final ReadingRepository readingRepository;
71	    private final RestrictionRepository restrictionRepository;
