74	    public WaterService(WaterUserRepository userRepository,
75	                        MeterRepository meterRepository,
76	                        PlanRepository planRepository,
77	                        ReadingRepository readingRepository,
78	                        RestrictionRepository restrictionRepository,
79	                        TimeProvider timeProvider) {
80	        this.userRepository = userRepository;
81	        this.meterRepository = meterRepository;
82	        this.planRepository = planRepository;
83	        this.readingRepository = readingRepository;
84	        this.restrictionRepository = restrictionRepository;
85	        this.timeProvider = timeProvider;
86	    }
