88	    @Transactional
89	    public UserView createUser(CreateUserRequest request) {
90	        Instant now = timeProvider.now();
91	        UserRow row = userRepository.create(request.name(), request.riverSection(),
92	                scale(request.annualQuota()), now);
93	        boolean restricted = restrictionRepository.findActive(row.riverSection()).isPresent();
94	        return new UserView(row.id(), row.name(), row.riverSection(), row.annualQuota(), restricted);
95	    }
96	
97	    @Transactional
98	    public MeterView createMeter(Long userId, CreateMeterRequest request) {
99	        UserRow user = userRepository.findById(userId)
100	                .orElseThrow(() -> new NotFoundException("取水户不存在: " + userId));
101	        MeterRow meter = meterRepository.create(user.id(), request.name());
102	        return new MeterView(meter.id(), meter.userId(), meter.name());
103	    }
