105	    @Transactional
106	    public DeclarationResult declare(DeclarationRequest request) {
107	        YearMonth month = YearMonth.parse(request.month(), MONTH_FORMATTER);
108	        BigDecimal declaredVolume = scale(request.volume());
109	
110	        // 1. 幂等记录优先：同键直接回放首次结果；异参在锁外即可判冲突。
111	        Optional<IdempotencyRow> existing = planRepository.findIdempotency(request.requestId());
112	        if (existing.isPresent()) {
113	            return replayOrConflict(request, declaredVolume, existing.get());
114	        }
115	
116	        Instant confirmedAt = timeProvider.now();
117	
118	        // 2. 锁定取水户行：同取水户并发申报串行化；限取触发也锁同一行，二者形成唯一先后顺序。
119	        UserRow user = userRepository.lockById(request.userId());
120	        if (user == null) {
121	            throw new NotFoundException("取水户不存在: " + request.userId());
122	        }
123	
124	        // 2.1 锁内二次检查幂等键，消除“锁外未见、并发请求抢先提交”的窗口。
125	        Optional<IdempotencyRow> concurrent = planRepository.findIdempotency(request.requestId());
126	        if (concurrent.isPresent()) {
127	            return replayOrConflict(request, declaredVolume, concurrent.get());
128	        }
129	
130	        // 3. 封存终态：修改与迟到申报一律拒绝（拒绝结果同样幂等记录）。
131	        int year = month.getYear();
132	        AnnualQuotaRow quota = userRepository.getOrCreateAnnualQuota(user.id(), year, user.annualQuota());
133	        if (quota.sealed()) {
134	            return recordRejection(request, declaredVolume, confirmedAt, quota, null,
135	                    "年度计划已封存，拒绝迟到申报");
136	        }
137	
138	        // 4. 限取判定：持锁后读取当前激活事件；生效时刻不晚于确认时刻（含同刻）即减半受理。
139	        Optional<RestrictionRow> active = restrictionRepository.findActive(user.riverSection());
140	        boolean restricted = active.isPresent()
141	                && !active.get().effectiveAt().isAfter(confirmedAt);
142	        Long restrictionId = restricted ? active.get().id() : null;
143	        BigDecimal acceptedVolume = restricted
144	                ? declaredVolume.divide(BigDecimal.valueOf(2), VOLUME_SCALE, RoundingMode.HALF_UP)
145	                : declaredVolume;
146	
147	        // 5. 已确认额度快照：本自然年各月最后已确认版本；当月旧版本将被本次替换，需扣除。
148	        List<PlanVersionRow> latestVersions = planRepository.findLatestVersionsOfYear(user.id(), year);
149	        BigDecimal othersAccepted = BigDecimal.ZERO;
150	        for (PlanVersionRow v : latestVersions) {
151	            if (!v.month().equals(request.month())) {
152	                othersAccepted = othersAccepted.add(v.acceptedVolume());
153	            }
154	        }
155	        BigDecimal effectiveQuota = quota.permittedQuota().subtract(quota.carryoverDeduction());
156	        BigDecimal candidateOccupied = othersAccepted.add(acceptedVolume);
157	
158	        if (candidateOccupied.compareTo(effectiveQuota) > 0) {
159	            // 超出剩余额度：整月拒绝，不产生新版本。
160	            return recordRejection(request, declaredVolume, confirmedAt, quota, restrictionId,
161	                    "申报超出许可剩余额度，整月申报拒绝");
162	        }
163	
164	        // 6. 受理：追加确认版本并落幂等指纹；唯一约束兜底并发同 requestId。
165	        PlanVersionRow version;
166	        try {
167	            version = planRepository.appendVersion(user.id(), request.month(), declaredVolume,
168	                    acceptedVolume, restricted, restrictionId, request.requestId(), confirmedAt);
169	            planRepository.insertIdempotency(new IdempotencyRow(request.requestId(), user.id(),
170	                    request.month(), declaredVolume, version.id(), false, null, confirmedAt));
171	        } catch (DuplicateKeyException dup) {
172	            IdempotencyRow winner = planRepository.findIdempotency(request.requestId())
173	                    .orElseThrow(() -> dup);
174	            return replayOrConflict(request, declaredVolume, winner);
175	        }
176	
177	        return new DeclarationResult(request.requestId(), user.id(), request.month(), "CONFIRMED",
178	                declaredVolume, acceptedVolume, version.version(), restricted,
179	                restricted ? active.get().effectiveAt().toString() : null, null);
180	    }
