182	    @Transactional
183	    public ReadingResult reportReading(ReadingRequest request) {
184	        Instant readingTime = Instant.parse(request.readingTime());
185	        BigDecimal cumulative = scale(request.cumulative());
186	
187	        MeterRow meter = meterRepository.findById(request.meterPointId())
188	                .orElseThrow(() -> new NotFoundException("计量点不存在: " + request.meterPointId()));
189	
190	        // 锁外快速去重；锁内仍会再查一次以消除并发窗口。
191	        Optional<ReadingRow> duplicate = readingRepository.findByMeterAndTime(meter.id(), readingTime);
192	        if (duplicate.isPresent()) {
193	            return toReadingResult(duplicate.get(), true);
194	        }
195	
196	        // 计量点父行锁串行化同点并发上报；读数不触碰申报额度。
197	        List<ReadingRow> ordered = readingRepository.lockOrderedReadings(meter.id());
198	        Optional<ReadingRow> concurrentDuplicate = readingRepository.findByMeterAndTime(
199	                meter.id(), readingTime);
200	        if (concurrentDuplicate.isPresent()) {
201	            return toReadingResult(concurrentDuplicate.get(), true);
202	        }
203	
204	        // 封存终态：锁取水户行后校验读数归属年度是否已封存，迟到读数一律拒绝。
205	        String month = YearMonth.from(readingTime.atOffset(ZoneOffset.UTC)).format(MONTH_FORMATTER);
206	        int readingYear = Integer.parseInt(month.substring(0, 4));
207	        UserRow owner = userRepository.lockById(meter.userId());
208	        AnnualQuotaRow yearQuota = userRepository.getOrCreateAnnualQuota(
209	                owner.id(), readingYear, owner.annualQuota());
210	        if (yearQuota.sealed()) {
211	            throw new BusinessRejectedException(
212	                    readingYear + " 年度计划已封存，拒绝迟到计量读数: " + request.readingTime());
213	        }
214	        ReadingRow predecessor = null;
215	        ReadingRow successor = null;
216	        for (ReadingRow r : ordered) {
217	            if (r.readingTime().isBefore(readingTime) || r.readingTime().equals(readingTime)) {
218	                predecessor = r;
219	            } else if (successor == null) {
220	                successor = r;
221	            }
222	        }
223	        BigDecimal delta;
224	        if (predecessor == null) {
225	            // 首个表底：增量以表底值作为起始用量。
226	            delta = cumulative;
227	        } else {
228	            delta = cumulative.subtract(predecessor.cumulative());
229	        }
230	        if (delta.compareTo(BigDecimal.ZERO) < 0) {
231	            throw new BusinessRejectedException("表底读数相对前一表底回退，拒绝入库: " + request.readingTime());
232	        }
233	        if (successor != null && successor.cumulative().compareTo(cumulative) < 0) {
234	            throw new BusinessRejectedException(
235	                    "表底读数大于后一表底读数，乱序插入会使后继增量为负，拒绝入库: " + request.readingTime());
236	        }
237	
238	        ReadingRow inserted = readingRepository.insert(meter.id(), readingTime, month,
239	                cumulative, delta, timeProvider.now());
240	
241	        // 乱序到达：新读数插入到表底序列中间时，重算后一读数的增量，保证月累计正确。
242	        if (successor != null) {
243	            BigDecimal successorDelta = successor.cumulative().subtract(cumulative);
244	            readingRepository.updateDelta(successor.id(), successorDelta);
245	        }
246	        return toReadingResult(inserted, false);
247	    }
