249	    @Transactional
250	    public RestrictionResult triggerRestriction(RestrictionRequest request) {
251	        // 先锁定河段全部取水户（按 ID 排序）：与已持锁的并发申报排队，形成唯一先后结果。
252	        List<UserRow> users = userRepository.lockByRiverSection(request.riverSection());
253	        Instant now = timeProvider.now();
254	        Instant requested = request.effectiveAt() == null || request.effectiveAt().isBlank()
255	                ? null : Instant.parse(request.effectiveAt());
256	        // 生效时刻不得早于拿到锁的时刻：排在本触发之前提交的申报不可能受尚未触发的事件影响。
257	        Instant effectiveAt = requested == null || requested.isBefore(now) ? now : requested;
258	        RestrictionRow row = restrictionRepository.trigger(request.riverSection(), effectiveAt,
259	                request.reason(), now);
260	        return new RestrictionResult(row.id(), row.riverSection(), row.effectiveAt().toString(),
261	                row.reason(), users.size());
262	    }
263	
264	    @Transactional(readOnly = true)
265	    public LedgerView ledger(Long userId, Integer year) {
266	        UserRow user = userRepository.findById(userId)
267	                .orElseThrow(() -> new NotFoundException("取水户不存在: " + userId));
268	        int targetYear = year != null ? year : timeProvider.now().atOffset(ZoneOffset.UTC).getYear();
269	        AnnualQuotaRow quota = userRepository.findAnnualQuota(user.id(), targetYear)
270	                .orElseGet(() -> new AnnualQuotaRow(null, user.id(), targetYear,
271	                        user.annualQuota(), BigDecimal.ZERO, false, null, null, null));
272	
273	        Map<String, MonthLineAccumulator> lines = new HashMap<>();
274	        BigDecimal declaredTotal = BigDecimal.ZERO;
275	        for (PlanVersionRow v : planRepository.findLatestVersionsOfYear(user.id(), targetYear)) {
276	            MonthLineAccumulator line = lines.computeIfAbsent(v.month(), m -> new MonthLineAccumulator(m));
277	            line.declared = v.declaredVolume();
278	            line.accepted = v.acceptedVolume();
279	            line.version = v.version();
280	            declaredTotal = declaredTotal.add(v.acceptedVolume());
281	        }
282	        BigDecimal actualTotal = BigDecimal.ZERO;
283	        for (MonthTotal t : readingRepository.monthlyTotalsOfUserYear(user.id(), targetYear)) {
284	            MonthLineAccumulator line = lines.computeIfAbsent(t.month(), MonthLineAccumulator::new);
285	            line.actual = t.total();
286	            actualTotal = actualTotal.add(t.total());
287	        }
288	
289	        BigDecimal effectiveQuota = quota.permittedQuota().subtract(quota.carryoverDeduction());
290	        BigDecimal remaining = effectiveQuota.subtract(declaredTotal);
291	        List<LedgerView.MonthLine> monthLines = new ArrayList<>();
292	        lines.values().stream().sorted((a, b) -> a.month.compareTo(b.month)).forEach(a ->
293	                monthLines.add(new LedgerView.MonthLine(a.month,
294	                        nz(a.declared), nz(a.accepted), nz(a.actual), a.version)));
295	        return new LedgerView(user.id(), targetYear, quota.permittedQuota(), quota.carryoverDeduction(),
296	                effectiveQuota, declaredTotal, actualTotal, remaining, quota.excess(), quota.sealed(),
297	                monthLines);
298	    }
299	
300	    @Transactional
301	    public SealResult seal(Long userId, Integer year) {
302	        UserRow user = userRepository.lockById(userId);
303	        if (user == null) {
304	            throw new NotFoundException("取水户不存在: " + userId);
305	        }
306	        int targetYear = year != null ? year : timeProvider.now().atOffset(ZoneOffset.UTC).getYear();
307	        AnnualQuotaRow quota = userRepository.getOrCreateAnnualQuota(user.id(), targetYear, user.annualQuota());
308	
309	        BigDecimal actualTotal = BigDecimal.ZERO;
310	        for (MonthTotal t : readingRepository.monthlyTotalsOfUserYear(user.id(), targetYear)) {
311	            actualTotal = actualTotal.add(t.total());
312	        }
313	
314	        if (quota.sealed()) {
315	            // 重复封存幂等：回放封存时刻冻结的实际水量与结算结果，终态固定。
316	            BigDecimal settledActual = quota.sealedActualTotal() == null ? BigDecimal.ZERO : quota.sealedActualTotal();
317	            BigDecimal settledExcess = quota.excess() == null ? BigDecimal.ZERO : quota.excess();
318	            return new SealResult(user.id(), targetYear, settledActual, quota.permittedQuota(),
319	                    quota.carryoverDeduction(),
320	                    quota.permittedQuota().subtract(quota.carryoverDeduction()),
321	                    settledExcess, settledExcess, true);
322	        }
323	
324	        // 超“许可年度总量”部分 1:1 结转次年；未超则结转 0（覆盖次年行可能存在的历史值）。
325	        BigDecimal excess = actualTotal.subtract(quota.permittedQuota()).max(BigDecimal.ZERO);
326	        userRepository.applySeal(quota, timeProvider.now(), actualTotal, excess, targetYear + 1);
327	        return new SealResult(user.id(), targetYear, actualTotal, quota.permittedQuota(),
328	                quota.carryoverDeduction(),
329	                quota.permittedQuota().subtract(quota.carryoverDeduction()),
330	                excess, excess, true);
331	    }
332	
333	    // ---- 独立辅助方法（置于作用域末尾）----
334	
335	    /**
336	     * 幂等回放或指纹冲突判定。
337	     */
338	    private DeclarationResult replayOrConflict(DeclarationRequest request, BigDecimal declaredVolume,
339	                                               IdempotencyRow row) {
340	        if (!row.userId().equals(request.userId())
341	                || !row.month().equals(request.month())
342	                || row.declaredVolume().compareTo(declaredVolume) != 0) {
343	            throw new IdempotencyConflictException(
344	                    "requestId 已用于不同申报参数（取水户/月份/水量不一致）: " + request.requestId());
345	        }
346	        if (row.rejected()) {
